/*
 * A209580  Triangle of coefficients of polynomials v(n,x) jointly generated
 *          with A209579; see the Formula section.
 * https://oeis.org/A209580
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) is the n‑th coefficient in a row‑wise traversal of the
 *            triangle of coefficients of the polynomials v(n,x) generated by
 *            u(1,x)=1, v(1,x)=1 u(n,x)=x*u(n‑1,x)+v(n‑1,x)
 *            v(n,x)=(x+1)*u(n‑1,x)+x*v(n‑1,x)+1 That is, let m be the
 *            smallest integer with m(m+1)/2 ≥ n. Let p = n - m(m‑1)/2 - 1 (0
 *            ≤ p <...
 * Range:     u8 n <= 39, u16 n <= 64, u32 n <= 64, u64 n <= 64, u128 n <= 64,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

seq_t a(idx_t termIndex)
{
    /* Find the row m such that sum_{k=1}^{m-1} k < termIndex ≤ sum_{k=1}^{m} k */
    idx_t low  = 1;
    idx_t high = termIndex;               /* high = termIndex is safe (≤ 2^64-1) */

    while (low < high) {
        idx_t mid = low + ((high - low) >> 1);
        __int128 sum = (__int128)mid * (mid + 1) / 2;
        if (sum >= termIndex)
            high = mid;
        else
            low = mid + 1;
    }
    idx_t m = low;                                       /* row number */
    __int128 prevSum = (__int128)m * (m - 1) / 2;          /* sum of rows before m */
    idx_t p = (idx_t)(termIndex - prevSum - 1);           /* index within row m (0‑based) */

    /* Special case: first row */
    if (m == 1)
        return 1;

    /* Allocate arrays for u(n−1,x) and v(n−1,x).  Initially n=1. */
    seq_t *u_prev = (seq_t *)malloc(sizeof(seq_t));
    seq_t *v_prev = (seq_t *)malloc(sizeof(seq_t));
    u_prev[0] = 1;
    v_prev[0] = 1;

    /* Build polynomials up to row m.  Each iteration increases degree by 1. */
    for (idx_t n = 2; n <= m; ++n) {
        seq_t *u_new = (seq_t *)calloc((size_t)n, sizeof(seq_t));
        seq_t *v_new = (seq_t *)calloc((size_t)n, sizeof(seq_t));

        /* k = 0 */
        u_new[0] = v_prev[0];
        v_new[0] = u_prev[0] + 1;

        /* k >= 1 */
        for (idx_t k = 1; k < n; ++k) {
            /* u(n) coefficient of x^k */
            seq_t sumu = u_prev[k - 1];
            if (k < n - 1)          /* v_prev has length n-1 */
                sumu += v_prev[k];
            u_new[k] = sumu;

            /* v(n) coefficient of x^k */
            seq_t sumv = u_prev[k - 1];
            if (k < n - 1)
                sumv += u_prev[k];
            sumv += v_prev[k - 1];
            v_new[k] = sumv;
        }

        /* Free previous arrays and advance pointers */
        free(u_prev);
        free(v_prev);
        u_prev = u_new;
        v_prev = v_new;
    }

    /* v_prev now holds v(m,x); extract the requested coefficient. */
    seq_t result = v_prev[p];
    free(u_prev);
    free(v_prev);
    return result;
}
